import 'package:drift/drift.dart';

import '../../features/review/domain/flashcard.dart';
import '../../features/review/domain/review_event.dart';
import '../../features/sentence_practice/domain/sentence_practice.dart';
import '../../features/vocabulary/domain/vocabulary_entry.dart';

// Schema conventions:
// - Primary keys are UUID strings generated by the app (stable across devices).
// - All DateTime values are written in UTC (stored as ISO-8601 text).
// - Enums are stored by name; renaming a value requires a migration.
// - Language columns store ISO codes such as 'de' and 'fa'.

@DataClassName('DeckRow')
class Decks extends Table {
  TextColumn get id => text()();
  TextColumn get name => text().withLength(min: 1, max: 80)();
  TextColumn get sourceLanguage => text().withLength(min: 2, max: 16)();
  TextColumn get definitionLanguage => text().withLength(min: 2, max: 16)();
  // Drift's idiom for referencing the column inside its own definition.
  IntColumn get dailyNewCardLimit =>
      integer()
      // ignore: recursive_getters
      .check(dailyNewCardLimit.isBetweenValues(0, 1000))();
  DateTimeColumn get createdAt => dateTime()();
  DateTimeColumn get updatedAt => dateTime()();

  @override
  Set<Column<Object>> get primaryKey => {id};
}

@DataClassName('VocabularyEntryRow')
@TableIndex(
  name: 'idx_entries_deck_normalized',
  columns: {#deckId, #normalized},
)
class VocabularyEntries extends Table {
  TextColumn get id => text()();
  TextColumn get deckId =>
      text().references(Decks, #id, onDelete: KeyAction.cascade)();
  TextColumn get original => text().withLength(min: 1)();
  TextColumn get normalized => text()();
  TextColumn get lemma => text().nullable()();
  TextColumn get sourceLanguage => text().withLength(min: 2, max: 16)();
  TextColumn get definitionLanguage => text().withLength(min: 2, max: 16)();
  TextColumn get partOfSpeech => text().nullable()();
  TextColumn get exampleSentence => text().nullable()();
  TextColumn get exampleTranslation => text().nullable()();
  TextColumn get grammarInfo => text().nullable()();
  TextColumn get notes => text().nullable()();
  TextColumn get sourceContext => text().nullable()();
  TextColumn get sourceType => textEnum<VocabularySourceType>()();
  TextColumn get enrichmentStatus => textEnum<EnrichmentStatus>()();

  /// JSON-encoded `EnrichmentMetadata`.
  TextColumn get enrichmentMetadata => text().nullable()();
  DateTimeColumn get userEditedAt => dateTime().nullable()();
  DateTimeColumn get createdAt => dateTime()();
  DateTimeColumn get updatedAt => dateTime()();

  /// UTC time the user marked the word as difficult; null when not marked
  /// (schema v2). A manual mark only: nothing sets it automatically.
  DateTimeColumn get markedDifficultAt => dateTime().nullable()();

  /// Comparison keys of the word, base form and meanings, one per line, for
  /// search (schema v2). Derived from the content and rewritten by the
  /// repository on every content change; never shown.
  TextColumn get searchKey => text().withDefault(const Constant(''))();

  @override
  Set<Column<Object>> get primaryKey => {id};
}

/// Meanings live in their own table so an entry can have any number of them
/// in a stable order.
@DataClassName('VocabularyMeaningRow')
class VocabularyMeanings extends Table {
  TextColumn get id => text()();
  TextColumn get entryId =>
      text().references(VocabularyEntries, #id, onDelete: KeyAction.cascade)();
  IntColumn get position => integer()();
  TextColumn get meaning => text().withLength(min: 1)();
  TextColumn get explanation => text().nullable()();

  @override
  Set<Column<Object>> get primaryKey => {id};

  @override
  List<Set<Column<Object>>> get uniqueKeys => [
    {entryId, position},
  ];
}

/// Review scheduling state. Separate from vocabulary content on purpose:
/// updating an entry never touches this table.
@DataClassName('FlashcardRow')
@TableIndex(name: 'idx_flashcards_due', columns: {#due})
class Flashcards extends Table {
  TextColumn get id => text()();
  TextColumn get entryId =>
      text().references(VocabularyEntries, #id, onDelete: KeyAction.cascade)();
  TextColumn get direction => textEnum<CardDirection>()();
  TextColumn get state => textEnum<CardState>()();
  IntColumn get step => integer().nullable()();
  RealColumn get stability => real().nullable()();
  RealColumn get difficulty => real().nullable()();
  DateTimeColumn get due => dateTime()();
  DateTimeColumn get lastReviewedAt => dateTime().nullable()();
  IntColumn get reviewCount => integer().withDefault(const Constant(0))();
  IntColumn get lapseCount => integer().withDefault(const Constant(0))();
  TextColumn get schedulerVersion => text().nullable()();
  DateTimeColumn get createdAt => dateTime()();
  DateTimeColumn get updatedAt => dateTime()();

  @override
  Set<Column<Object>> get primaryKey => {id};

  @override
  List<Set<Column<Object>>> get uniqueKeys => [
    {entryId, direction},
  ];
}

/// User-defined labels such as "B1" or "travel" (schema v2).
@DataClassName('TagRow')
class Tags extends Table {
  TextColumn get id => text()();

  /// As entered (whitespace cleaned).
  TextColumn get name => text().withLength(min: 1, max: 40)();

  /// Case-insensitive key; two tags cannot differ only in case or spacing.
  TextColumn get nameKey => text().unique()();
  DateTimeColumn get createdAt => dateTime()();
  DateTimeColumn get updatedAt => dateTime()();

  @override
  Set<Column<Object>> get primaryKey => {id};
}

/// Which tags an entry has (schema v2). Deleting an entry or a tag removes
/// only the assignment rows.
@DataClassName('EntryTagRow')
@TableIndex(name: 'idx_entry_tags_tag', columns: {#tagId})
class EntryTags extends Table {
  TextColumn get entryId =>
      text().references(VocabularyEntries, #id, onDelete: KeyAction.cascade)();
  TextColumn get tagId =>
      text().references(Tags, #id, onDelete: KeyAction.cascade)();
  DateTimeColumn get createdAt => dateTime()();

  @override
  Set<Column<Object>> get primaryKey => {entryId, tagId};
}

/// Explicitly recorded reviews (schema v2). History is kept when the word is
/// deleted: [entryId] is set to null.
@DataClassName('ReviewEventRow')
@TableIndex(name: 'idx_review_events_day', columns: {#localDay})
class ReviewEvents extends Table {
  TextColumn get id => text()();
  TextColumn get entryId => text().nullable().references(
    VocabularyEntries,
    #id,
    onDelete: KeyAction.setNull,
  )();
  TextColumn get sessionId => text()();
  TextColumn get direction => textEnum<CardDirection>()();
  TextColumn get outcome => textEnum<ReviewOutcome>()();
  DateTimeColumn get reviewedAt => dateTime()();

  /// `YYYY-MM-DD`, the device's local day at recording time.
  TextColumn get localDay => text().withLength(min: 10, max: 10)();

  @override
  Set<Column<Object>> get primaryKey => {id};
}

/// Small local key-value settings, e.g. the study reminder (schema v2).
/// Never holds secrets: the AI key stays in OS secure storage.
@DataClassName('AppSettingRow')
class AppSettings extends Table {
  TextColumn get key => text()();
  TextColumn get value => text()();

  @override
  Set<Column<Object>> get primaryKey => {key};
}

/// Sentence-practice history (schema v3): which word was practised, when,
/// how and with what result. No answers or AI text are stored. Separate
/// from `review_events`, so it never affects FSRS, statistics or streaks;
/// deleting a word deletes its sentence-practice history.
@DataClassName('SentencePracticeEventRow')
@TableIndex(name: 'idx_sentence_practice_entry', columns: {#entryId})
class SentencePracticeEvents extends Table {
  TextColumn get id => text()();
  TextColumn get entryId =>
      text().references(VocabularyEntries, #id, onDelete: KeyAction.cascade)();
  TextColumn get direction => textEnum<SentencePracticeDirection>()();
  TextColumn get level => textEnum<SentenceLevel>()();
  TextColumn get outcome => textEnum<SentencePracticeOutcome>()();
  DateTimeColumn get practicedAt => dateTime()();

  @override
  Set<Column<Object>> get primaryKey => {id};
}

/// How a word's card looks (schema v4): colours, text sizes, highlights and
/// a sticker. One optional row per word; no row means the standard look.
/// Presentation only, kept apart from the content so styling a card never
/// changes the word's `updated_at` or its review state. Choices are stored
/// by name (unknown names read as the default).
@DataClassName('CardAppearanceRow')
class CardAppearances extends Table {
  TextColumn get entryId =>
      text().references(VocabularyEntries, #id, onDelete: KeyAction.cascade)();
  TextColumn get background => text().nullable()();
  TextColumn get ink => text().nullable()();
  RealColumn get wordScale => real().withDefault(const Constant(1))();
  RealColumn get meaningScale => real().withDefault(const Constant(1))();
  TextColumn get highlightColor => text().nullable()();

  /// JSON list of `{"f": "word"|"meaning", "t": text}`.
  TextColumn get highlights => text().withDefault(const Constant('[]'))();
  TextColumn get sticker => text().nullable()();
  DateTimeColumn get updatedAt => dateTime()();

  @override
  Set<Column<Object>> get primaryKey => {entryId};
}
